import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Lock } from 'lucide-react';
import BlogFeed from './components/BlogFeed';
import BlogPost from './components/BlogPost';
import AdminPanel from './components/AdminPanel';
import { initialPosts } from './data/blogPosts';
import './App.css';

function AppContent() {
  const [posts, setPosts] = useState(initialPosts);
  const [showAdminAuth, setShowAdminAuth] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');
  const [isAdminAuth, setIsAdminAuth] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const handleMouseMove = (e) => {
    const cursor = document.querySelector('.cursor-glow');
    if (cursor) {
      cursor.style.left = e.clientX + 'px';
      cursor.style.top = e.clientY + 'px';
    }
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  const handleAdminLogin = (e) => {
    e.preventDefault();
    if (adminPassword === 'admin123') {
      setIsAdminAuth(true);
      setShowAdminAuth(false);
      setAdminPassword('');
      navigate('/admin');
    } else {
      alert('Invalid password');
      setAdminPassword('');
    }
  };

  const handleAddPost = (newPost) => {
    const post = {
      id: Math.max(...posts.map((p) => p.id), 0) + 1,
      ...newPost,
      author: 'Naduni Wanniarachchi',
      date: new Date().toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
      }),
    };
    setPosts([post, ...posts]);
    alert('Post published successfully!');
  };

  const handleEditPost = (id, updatedData) => {
    setPosts(
      posts.map((post) =>
        post.id === id
          ? {
              ...post,
              ...updatedData,
            }
          : post
      )
    );
    alert('Post updated successfully!');
  };

  const handleDeletePost = (id) => {
    setPosts(posts.filter((post) => post.id !== id));
    alert('Post deleted successfully!');
  };

  return (
    <div className="App">
      <div className="cursor-glow" />

      {/* Header */}
      {!location.pathname.includes('/admin') && !location.pathname.includes('/post/') && (
        <header className="app-header-blog">
          <div className="header-container">
            <div className="header-left">
              <h1 className="site-title">ProdTrack</h1>
              <p className="site-subtitle">Tech Blog & Insights</p>
            </div>
            <nav className="header-nav">
              <button
                className="nav-btn"
                onClick={() => setShowAdminAuth(true)}
              >
                <Lock size={16} />
                Admin
              </button>
            </nav>
          </div>
        </header>
      )}

      {/* Admin Auth Modal */}
      {showAdminAuth && !isAdminAuth && (
        <motion.div
          className="modal-overlay"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          onClick={() => setShowAdminAuth(false)}
        >
          <motion.div
            className="admin-auth-modal"
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            onClick={(e) => e.stopPropagation()}
          >
            <h2>Admin Access</h2>
            <form onSubmit={handleAdminLogin}>
              <input
                type="password"
                placeholder="Enter admin password"
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                autoFocus
              />
              <div className="modal-actions">
                <button type="submit" className="btn-primary">
                  Login
                </button>
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => setShowAdminAuth(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </motion.div>
        </motion.div>
      )}

      {/* Routes */}
      <Routes>
        <Route path="/" element={<BlogFeed posts={posts} />} />
        <Route path="/post/:id" element={<BlogPost posts={posts} />} />
        <Route
          path="/admin"
          element={
            isAdminAuth ? (
              <AdminPanel
                posts={posts}
                onAddPost={handleAddPost}
                onDeletePost={handleDeletePost}
                onEditPost={handleEditPost}
              />
            ) : (
              <div style={{ textAlign: 'center', padding: '100px 20px' }}>
                <h2>Access Denied</h2>
                <p>Please use the admin button to authenticate.</p>
              </div>
            )
          }
        />
      </Routes>
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;
